-- Catálogo editable de conceptos financieros, basado inicialmente en BdCols
-- de MOVIMIENTOS CAJA 2026 (gid 1966410681), exportado el 24/09/2026.
ALTER TABLE public.cash_transactions
  ADD COLUMN IF NOT EXISTS efe_category TEXT;

CREATE TABLE IF NOT EXISTS public.financial_concepts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  concept TEXT NOT NULL CHECK (length(btrim(concept)) > 0),
  category TEXT NOT NULL CHECK (length(btrim(category)) > 0),
  sub_category TEXT NOT NULL DEFAULT '',
  movement_type TEXT NOT NULL CHECK (movement_type IN ('Ingreso', 'Egreso', 'Mov. Financiero')),
  efe_category TEXT NOT NULL DEFAULT '',
  is_active BOOLEAN NOT NULL DEFAULT true,
  source_row INTEGER UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS financial_concepts_concept_idx
  ON public.financial_concepts (lower(concept));

ALTER TABLE public.financial_concepts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS financial_concepts_read ON public.financial_concepts;
CREATE POLICY financial_concepts_read ON public.financial_concepts
  FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS financial_concepts_manage ON public.financial_concepts;
CREATE POLICY financial_concepts_manage ON public.financial_concepts
  FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Datos originales de BdCols. source_row permite reejecutar la migración sin duplicar filas.
ON CONFLICT (source_row) DO NOTHING;
